CREATE TABLE IF NOT EXISTS duranki_auth_identity (user_id VARCHAR(191) COLLATE utf8mb4_bin PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS duranki_auth_session (jti VARCHAR(191) COLLATE utf8mb4_bin PRIMARY KEY, user_id VARCHAR(191) COLLATE utf8mb4_bin NOT NULL, expires_at BIGINT NOT NULL, last_seen BIGINT NOT NULL, revoked TINYINT NOT NULL DEFAULT 0, KEY auth_session_user(user_id), KEY auth_session_expiry(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS duranki_mfa_credential (user_id VARCHAR(191) COLLATE utf8mb4_bin PRIMARY KEY, secret TEXT NOT NULL, version VARCHAR(191) COLLATE utf8mb4_bin NOT NULL, last_step BIGINT NOT NULL, recovery LONGTEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS duranki_mfa_challenge (id VARCHAR(191) COLLATE utf8mb4_bin PRIMARY KEY, user_id VARCHAR(191) COLLATE utf8mb4_bin NOT NULL, expires BIGINT NOT NULL, attempts INT NOT NULL DEFAULT 0, pending_secret TEXT NULL, claims LONGTEXT NOT NULL, KEY mfa_challenge_user(user_id), KEY mfa_challenge_expiry(expires)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS duranki_mfa_audit (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id VARCHAR(191) COLLATE utf8mb4_bin NOT NULL, event VARCHAR(80) NOT NULL, created_at VARCHAR(40) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS duranki_auth_migration (id INT PRIMARY KEY, source_sha256 CHAR(64) NOT NULL, key_sha256 CHAR(64) NOT NULL, counts_json LONGTEXT NOT NULL, migrated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
